// Injected only into html_preview, never into the distributed prototype.
(()=>{const {d,render,controls}=prototypeUI,$=id=>document.getElementById(id),saved=JSON.parse(JSON.stringify(d)),results=[];let assertions=0;
function check(ok,message){assertions++;if(!ok)throw Error(message);}
function run(name,fn){try{fn();results.push({name,passed:true})}catch(e){results.push({name,passed:false,error:e.message});if($('modal').open)$('modal').close();d.discard();}}
function change(id,value){$(id).value=value;$(id).dispatchEvent(new Event('change',{bubbles:true}));}
function clickText(text){const b=[...$('modal').querySelectorAll('button')].find(x=>x.textContent===text);check(!!b,'Missing modal action '+text);b.click();}
run('blank → LabelledSlider → exposed API → Apply',()=>{ $('new').click();change('new-name','JourneySlider');clickText('Create blank');check(d.draft.nodes.length===0,'blank starts empty');check($('component').offsetHeight===48,'empty Hug clamps outer min to 48; chrome excluded');change('insert-kind','Text');$('insert').click();change('insert-kind','Slider');$('insert').click();change('property-type','Number');$('expose').click();check(d.draft.api.value.type==='Number','numeric exposure');check(!d.catalog[d.draft.id],'draft not confirmed');$('apply').click();check(!d.dirty,'Apply confirms');check($('layers').children.length===2,'two visible layer entries');});
run('layout authoring and draft undo',()=>{change('gap','24');check(d.draft.layout.gap===24,'gap saved to draft');check($('component').style.gap==='24px','gap preview');$('undo').click();check(d.draft.layout.gap===8,'undo restores gap');change('flow','row');check($('component').style.flexDirection==='row','row preview');$('discard').click();check(d.draft.layout.flow==='column','discard restores flow');});
run('Test slider changes sample only',()=>{$('test-mode').click();const x=$('component').querySelector('input[type=range]');check(!x.disabled,'Test enabled slider');x.value='77';x.dispatchEvent(new Event('input',{bubbles:true}));check(Object.values(d.values).includes('77'),'sample captured');check(!d.dirty,'Test does not dirty source');$('edit-mode').click();check($('component').querySelector('input[type=range]').disabled,'Edit disables sample control');});
run('mode, named color outlet and reset',()=>{$('appearance-light').click();check(!d.dirty,'mode preview local');change('text-color','#123456');check(d.draft.colors.Light.text==='#123456','mode color in draft');change('instance-color','#abcdef');$('override').click();check($('instance-source').textContent.includes('override'),'override provenance');$('reset').click();check($('instance-sample').style.color==='rgb(18, 52, 86)','Reset resolves changed default');$('apply').click();$('appearance-dark').click();check(!d.dirty,'mode switch remains local');});
run('stale Apply reports conflict and retains draft',()=>{change('gap','20');$('technical-details').open=true;$('simulate-remote').click();$('apply').click();check($('message').textContent.includes('Review changes'),'actionable conflict diagnostic');check(d.draft.layout.gap===20,'draft retained');check($('draft-status').textContent==='Changes need review','conflict save status');$('rebase').click();$('apply').click();check(!d.dirty,'explicit model rebase can apply');$('technical-details').open=false;});
run('both sizing axes, stored Fixed values, bounds and definite Fill',()=>{for(const width of ['Fixed','Hug','Fill'])for(const height of ['Fixed','Hug','Fill']){change('width',width);change('height',height);if(width==='Fixed')change('fixed-w','321');if(height==='Fixed')change('fixed-h','187');check($('fixed-w').disabled===(width!=='Fixed'),'Fixed W gating '+width);check($('fixed-h').disabled===(height!=='Fixed'),'Fixed H gating '+height);const f=$('component');if(width==='Fixed')check(f.offsetWidth===321,'actual Fixed W');if(width==='Fill')check(f.offsetWidth===document.querySelector('.stage').clientWidth-32,'Fill uses finite parent W');if(height==='Fixed')check(f.offsetHeight===187,'actual Fixed H');if(height==='Fill')check(f.offsetHeight===320,'Fill uses finite parent H');}change('height','Fixed');check($('fixed-h').value==='187','fixed height retained across mode changes');change('min-h','200');check($('component').offsetHeight===200,'minimum clamps outer H');change('max-h','190');check($('apply').disabled,'invalid bound disables Apply');check($('layout-error').textContent.includes('maxH'),'bound error explained');check($('draft-status').textContent==='Fix invalid values before applying','invalid save status');change('max-h','240');check(!$('apply').disabled,'corrected bound admissible');$('discard').click();});
run('distribution, alignment, clip and invalid numeric drafts',()=>{change('distribution','between');const cells=[...$('align').children];check(cells.filter(b=>!b.disabled).length===3,'only cross-axis alignment offered');check(cells.some(b=>!b.disabled&&b.getAttribute('aria-pressed')==='true'),'selected alignment is enabled');$('clip').checked=true;$('clip').dispatchEvent(new Event('change',{bubbles:true}));check($('component').style.overflow==='hidden','clip applied');change('padding','-1');check($('apply').disabled,'negative padding blocks Apply');change('padding','16');change('gap','');check($('apply').disabled,'blank numeric is not zero');$('test-mode').click();check($('gap').value==='','blank field draft survives unrelated rerender');check($('apply').disabled,'invalid raw draft remains blocked');$('edit-mode').click();change('gap','8');$('discard').click();});
run('layer name independent of content; Edit/Test chrome does not change Hug size',()=>{d.selection=d.draft.nodes[0].id;render();change('node-name','Header layer');check(d.draft.nodes[0].label==='Label','layer rename leaves content');change('node-label','Visible heading');check(d.draft.nodes[0].name==='Header layer','content edit leaves layer name');change('height','Hug');const before=$('component').offsetHeight;$('test-mode').click();check($('component').offsetHeight===before,'selection chrome excluded from layout');$('edit-mode').click();$('discard').click();});
for(const kind of controls)run('control render and interaction / '+kind,()=>{d.create('Browser '+kind);d.insert(kind);d.apply();d.test=true;render();const widget=$('component').querySelector('[data-kind="'+kind+'"]');check(!!widget,'widget rendered');check(widget.getBoundingClientRect().width>0,'widget has width');const x=widget.querySelector('input,select,button');if(x){check(!x.disabled,'sample enabled');if(x.tagName==='BUTTON')x.click();else if(x.tagName==='SELECT'){x.value='High';x.dispatchEvent(new Event('change',{bubbles:true}));}else{if(x.type==='checkbox')x.checked=true;else x.value=x.type==='range'?'35':x.type==='number'?'23':'Edited';x.dispatchEvent(new Event('input',{bubbles:true}));}if(kind==='Dialog'){check($('modal').open,'modal specimen opens');clickText('Cancel');}else check(Object.keys(d.values).some(k=>k===d.draft.nodes[0].id),'interaction reaches sample state');}if(x&&kind!=='Dialog')check(x.isConnected,'active control retained during interaction');check(!d.dirty,'sample did not edit source');d.test=false;render();});
run('in-use deletion modal blocks; retire prevents new use',()=>{d.create('Consumer');d.insert('LabelledSlider');d.apply();d.open('LabelledSlider');render();$('delete').click();check($('modal-body').textContent.includes('Blocked'),'impact visible');clickText('Delete definition');check($('message').textContent.includes('In use'),'delete rejected');check(!!d.catalog.LabelledSlider,'definition retained');clickText('Cancel');$('retire').click();clickText('Retire definition');check(!d.catalog.LabelledSlider.retired,'retire staged');$('apply').click();check(d.catalog.LabelledSlider.retired,'retired');check(![...$('insert-kind').options].some(x=>x.value==='LabelledSlider'),'retired absent from insert');});
run('pending deletion disables authoring and undo restores it',()=>{d.create('DeleteCandidate');d.apply();render();$('delete').click();clickText('Delete definition');check($('draft-status').textContent.includes('Pending deletion'),'tombstone status');check($('insert').disabled&&$('name').disabled,'ordinary edits disabled');$('undo').click();check(!$('name').disabled,'Undo re-enables edits');check(!d.dirty,'Undo clears tombstone');});
run('Publish is explicit separate snapshot',()=>{$('publish').click();clickText('Snapshot confirmed model');check(d.published!==null,'snapshot produced');check($('message').textContent.includes('no external'),'simulation labeled');});
run('inspector scroll reaches lifecycle actions',()=>{$('tab-Inspect').click();render();const panel=document.querySelector('.right');panel.scrollTop=panel.scrollHeight;const target=$('delete').getBoundingClientRect(),bounds=panel.getBoundingClientRect();check(target.top>=bounds.top&&target.bottom<=bounds.bottom,'Delete reachable inside scrolling inspector');panel.scrollTop=0;});
run('workspace tabs distinct from interaction mode and appearance',()=>{check(!$('profile'),'device profile selector removed');const before=JSON.stringify(d.draft),mode=d.test;for(const pane of ['Library','Layers','Inspect']){$('tab-'+pane).click();check($('tab-'+pane).getAttribute('aria-selected')==='true','active tab '+pane);check(!$(pane==='Inspect'?'inspect-panel':pane==='Library'?'catalog-section':'layers-section').hidden,'matching panel visible');check(d.test===mode,'navigation does not change interaction');}check(JSON.stringify(d.draft)===before,'tabs do not mutate source');$('inspect-panel').scrollTop=80;const anchor=$('inspect-panel').scrollTop;$('tab-Library').click();$('tab-Inspect').click();check($('inspect-panel').scrollTop===anchor,'inspector scroll restored across tabs');$('inspect-panel').scrollTop=0;$('tab-Library').focus();$('tab-Library').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));check(document.activeElement===$('tab-Layers'),'arrow key moves tab focus');check(rootPane()==='Layers','arrow key activates panel');$('tab-Inspect').click();});
run('matching appearance switch and useful single save status',()=>{d.discard();render();check($('draft-status').textContent==='All changes applied','clean status');check(!$('appearance'),'appearance dropdown removed');check($('appearance-dark').closest('.mode-switch')&&$('edit-mode').closest('.mode-switch'),'same switch component');const before=JSON.stringify(d.draft),interaction=d.test;$('appearance-light').click();check($('appearance-light').getAttribute('aria-pressed')==='true','Light selected');check($('appearance-dark').getAttribute('aria-pressed')==='false','Dark unselected');check(JSON.stringify(d.draft)===before&&d.test===interaction,'appearance local and independent');check($('draft-status').textContent==='All changes applied','preview does not imply edits');d.change(x=>x.layout.gap=17);render();check($('draft-status').textContent==='Unapplied changes','dirty status');check(!$('revision').closest('details').open,'revision hidden in collapsed details');check(document.querySelectorAll('#draft-status').length===1,'one save-status surface');$('discard').click();check($('draft-status').textContent==='All changes applied','discard status');$('appearance-dark').click();});
run('responsive width changes preserve editing context',()=>{const root=$('designer'),before=JSON.stringify(d.draft),mode=d.test,selection=d.selection,tab=root.dataset.pane;const panel=$('inspect-panel');panel.scrollTop=80;for(const width of [1024,728,1280]){root.style.width=Math.min(width,innerWidth-16)+'px';check(root.scrollWidth<=root.clientWidth,'workspace fits width '+width);check(root.dataset.pane===tab&&d.test===mode,'navigation and interaction retained');check(d.selection===selection&&JSON.stringify(d.draft)===before,'selection and draft retained');}root.style.width='';panel.scrollTop=0;prototypeUI.fitWorkspace(600);const small=root.querySelector('.workspace').offsetHeight;prototypeUI.fitWorkspace(900);check(root.querySelector('.workspace').offsetHeight>small,'work height adapts to available height');check(JSON.stringify(d.draft)===before,'height resize does not mutate draft');prototypeUI.fitWorkspace();});
function rootPane(){return $('designer').dataset.pane;}
Object.assign(d,saved);$('designer').dataset.pane='Inspect';render();document.activeElement?.blur();requestAnimationFrame(()=>{const report={kind:'OIB_DESIGNER_BROWSER_TESTS',cases:results.length,assertions,passed:results.filter(x=>x.passed).length,failed:results.filter(x=>!x.passed),results,viewport:{width:innerWidth,height:innerHeight},shellHeight:$('designer').getBoundingClientRect().height,overflow:document.documentElement.scrollWidth>innerWidth};console.info(JSON.stringify({...report,results:undefined}));});})();
